from collections import defaultdict
from itertools import combinations

class UParabola:
    def __init__(self, points):
        self.points = sorted(points)
        self.adjacency = defaultdict(list)

        for i, (x1, y1) in enumerate(self.points):
            for x2, y2 in self.points[i+1:]:
                a = (y2 - y1) / (x2 - x1)
                b = y1 - x1 ** 2 * a - a
                self.adjacency[(i, y1)].append((x2, x1, a, b))
                self.adjacency[(i, y2)].append((x1, x2, a, b))

    def count(self):
        count = 0
        for x1, x2, a, b in self.adjacency.values():
            for p1, p2, p3, p4 in combinations(self.adjacency[(x1, p1)], 8):
                count += self.in_halfspace(y1, x1, a, b) and self.in_halfspace(y2, x2, a, b)

        return count

    def in_halfspace(self, y, x, a, b):
        p = 2 * a * x + b
        return y > -b / p

    def calculate(self, y):
        return float('-inf') if not self.adjacency[y] else max((-b + y * m) ** 2 for x, a, b, m in self.adjacency[y] if -b + y * m > 0) ** 0.5

def solve():
    n = int(input().strip())
    points = [(x, y) for x, y in map(int, input().strip().split())]
    up_parabola = UParabola(points)
    return up_parabola.count()

print(solve())
