import sys

def find_path(graph):
    """Find a simple path with length at least n/k."""
    visited = [False] * len(graph)
    path = []
    stack = [0]

    while stack:
        node = stack.pop()
        if visited[node]:
            path.append(node)
            continue
        visited[node] = True
        path.append(node)
        for neighbor in range(len(graph)):
            if graph[node][neighbor] == 1:
                stack.append(neighbor)
                break

    if len(path) * 2 >= len(graph):
        return 'PATH\n' + str(len(path)) + '\n' + ' '.join(str(x) for x in path)
    else:
        return '-1'

def find_cycles(graph):
    """Find k cycles with length at least 3, not divisible by 3, and each vertex appears only once in at least one cycle."""
    visited = [False] * len(graph)
    cycles = []

    for i in range(len(graph)):
        if not visited[i]:
            path = [i]
            path_left = len(graph) - 1
            rec_path = []
            stack = [i]

            while stack and path_left > 1:
                node = stack.pop()
                visited[node] = True
                rec_path.append(node)
                path.append(node)
                for neighbor in range(len(graph)):
                    if graph[node][neighbor] == 1:
                        stack.append(neighbor)
                        break
                else:
                    continue
                path_left -= 1
            if len(rec_path) >= 3 and len(rec_path) % 3 != 0:
                cycles.append(' '.join(str(x) for x in path))

    if len(cycles) >= 2 * len(graph):
        return 'CYCLES\n' + '\n'.join(cycles[::2])
    else:
        return '-1'

