def find_path(graph, start, end):
    path = [start]
    visited = {start}
    while start != end:
        for neighbor in graph[start]:
            if neighbor not in visited and (2 <= graph[start][neighbor] <= 2):
                path.append(neighbor)
                visited.add(neighbor)
                start = neighbor
                break
    return path

def find_cycles(graph, k):
    cycles = []
    for start in graph:
        if len(graph[start]) >= 3:
            cycle_start = find_path(graph, start, 0)[0]
            cycle = [cycle_start]
            k -= 1
            while graph[cycle_start][cycle[0]]:
                cycle_start = last_node = cycle.pop()
                for prev in graph[cycle_start]:
                    if prev not in last_node:
                        cycle.append(prev)
            if graph[cycle_start][last_node]:
                cycle.append(last_node)
                spins = len(graph[cycle_start][last_node])
                if (spins - 1) % ((spins - 2) + (spins - 1)) != 0:
