import math

def count_divisors(a, b, k):
    count = 0
    if k < a or k > b:
        return 0
    elif a >= k:
        lower_start = max(1, b // (k * sum(2 ** i for i in range(k))))
        lower_end = b // k
    else:
        lower_start = 1
        higher_end = b - (k * sum(2 ** i for i in range(k)))

    if k == 1:
        return (higher_end - lower_start) + 1
    elif k < lower_start:
        return 0
