from math import sqrt

def find_divisors(n, k):
    """Find divisors of n that are less than or equal to k."""
    divisors = []
    for i in range(1, int(sqrt(k)) + 1):
        if n % i == 0 and i <= k:
            divisors.append(i)
            if i != n // i:
                divisors.append(n // i)
    return divisors

def count_divisor_free_numbers(a, b, k):
    """Count numbers in the range [a, b] that have a smallest divisor equal to k."""
    divisor_free = 0
    for n in range(a, b + 1):
        if all(n % d != 0 for d in find_divisors(n, k)):
            divisor_free += 1
    return divisor_free

