import sys
import heapq

def solve_kc(n, m, k):
    graph = [[] for _ in range(n + 1)]
    for _ in range(m):
        u, v = map(int, sys.stdin.readline().split())
        graph[u].append(v)
        graph[v].append(u)

    visit = [False] * (n + 1)
    distance = [float('inf')] * (n + 1)
    distance[1] = 0

    pq = [(0, 1)]
    while pq:
        d, u = heapq.heappop(pq)
        if visit[u]:
            continue
        visit[u] = True
        for v in graph[u]:
            if visit[v]:
                continue
            if d < distance[v]:
                distance[v] = d
                heapq.heappush(pq, (distance[v], v))

    if distance[n] < k:
        return -1

    kc = distance[n]
    cycles = []
    for _ in range(k):
        visited = [False] * (n + 1)
        stack = [(0, 1)]
        while stack:
            d, u = stack.pop()
            if visited[u]:
                continue
            if distance[u] >= d * k:
                cycles.append(list(stack))
                break
            visited[u] = True
            for v in graph[u]:
                if visited[v]:
                    continue
                if distance[v] >= d:
                    stack.append((d, v))

    if not cycles:
        return -1

    return kc if kc >= n // k else 1

