class SegmentTree:
    def __init__(self, n):
        self.n = n
        self.tree = [0] * (4 * n)
        self.lazy = [0] * 4 * n

    def update(self, node, start, end, idx, x):
        if idx < start or idx > end:
            return
        if start == end:
            self.tree[node] = x
            return self
        lazy = self.lazy[node]
        self.lazy[2 * node] = lazy
        self.lazy[2 * node + 1] = lazy
        self.tree[node] = x
        start = (start + end) // 2
        end = (start + end) % 2 + (end + end) // 2
        if lazy:
            self.lazy = [0] * 4 * n
        return

    def update_range(self, node, start, end, l, r, x):
        lazy = self.lazy[node]
        self.lazy[2 * node] = lazy
        self.lazy[2 * node + 1] = lazy
        if lazy:
            self.lazy = [0] * 4 * n

        if r < start or l > end:
            return
        if l <= start and end <= r:
            self.update(node, start, end, x)
            return self

        start = (start + end) // 2
        end = (start + end) % 2 + (end + end) // 2
        if lazy:
            self.lazy = [0] * 4 * n

        self.update_range(2 * node, start, middle, l, r, x)
        self.update_range(2 * node + 1, middle + 1, end, l, r, x)
        self.tree[node] = self.tree[2 * node] + self.tree[2 * node + 1]

    def query_range(self, node, start, end, l, r):
        lazy = self.lazy[node]
        self.lazy[2 * node] = lazy
        self.lazy[2 * node + 1] = lazy
        if lazy:
            self.lazy = [0] * 4 * n

        if r < start or l > end:
            return 0
        if l <= start and end <= r:
            return self.tree[node]

        start = (start + end) // 2
        end = (start + end) % 2 + (end + end) // 2
        if lazy:
            self.lazy = [0] * 4 * n

        mid = (2 * node) + 1
        return self.query_range(2 * node, start, middle, l, r) + self.query_range(2 * node + 1, middle + 1, end, l, r)

    def query_all(self):
        return self.query_range(1, 1, self.n, 1, self.n)


def solve(n, query):
    segment = SegmentTree(n)
    for query_type, l, r, x in query:
        if query_type == 1:
            segment.update(1, 1, n, l, r, segment.query_all() + abs(x - (l % n)) + abs(x - ((r - 1 + n) % n)))
        elif query_type == 2:
            print(segment.query_range(1, 1, n, l, r))


