            return "CYCLES\n"
        while True:
            reps = [i + 1 for i in range(self.n) if result.count(i + 1) == 2]
            cycles = []
            for rep in reps:
                cycle = result[result.index(rep) + 1:]
                reverse_cycle = cycle[::-1]
                cycle_not_reverse = cycle
                if (cycle_not_reverse[-1] == rep - 1 and not cycle[-1] == rep + 1) or \
