import heapq

def isGoodGame(n, k, coins):
    # Input Task:
    # Two integers n and k, where 1 ≤ n ≤ 10^{9}, 0 ≤ k ≤ 2⋅10^5
    # k integer pairs of numbers representing pirates and the coins they have at the start, where 1 ≤ a_i ≤ n and 1 ≤ b_i ≤ 10^{9}
    # Output T/F for whether the game is good or not

    if n % 2 == 0 and k > 0:
        return -1  # At least one pirate needs to have 2 or more coins to start splitting

    transits = []  # Stores the sum of coins for each possible start split

    # Generate possible total coin states and sort them
    for i in range(n // 2 + 1):
        total = sum([b for _, b in coins])
        a = total // (i + 1)
        if total % (i + 1) != 0:
            a += 1
        transits.append(a)

    for c, b in coins:
        transits[transits.index(c * b)] -= b

    transits.sort()  # Sort to find consecutive zero values

    # Special cases where splitting will fail
    for i in range(1, len(transits)):
        if transits[i] == transits[i - 1] and transits[i - 1] != 0:
            return  # Splitting fails
        elif transits[i] == transits[i - 1] * -1:
            return -1

    for i in range(len(transits)):
        if transits[i] * -1 in transits[i + 1:] and transits[i] != 0:
            return -1  # Splitting fails

    return 1

