import sys

def minimal_cost_descension(n, sequence):
    dp = [0] * n
    dp[0] = sequence[0]
    for i in range(1, n):
        min_cost = sequence[i-1] + sequence[i]
        for j in range(i-1):
            min_cost = min(min_cost, dp[j] + sequence[i])
        dp[i] = min_cost
    return dp[n-1]

def find_descension_sequence(n, sequence, dp):
    descension_sequence = []
    i = n - 1
    while i > 0:
        while i > 0 and sequence[i] == dp[i-1]:
            i -= 1
        descension_sequence.append(i)
        if i == 0:
            break
        min_cost = dp[i-1] + dp[i]
        for j in range(i-1, 0):
            if dp[j] + dp[i] < min_cost:
                min_cost = dp[j] + dp[i]
                i = j
    return descension_sequence

