from collections import defaultdict

def solve(n, values, edges):
    parent = [-1] * (n+1)
    rank = [0] * (n+1)
    solution = 0

    for edge in edges:
        u, v = edge
        if u == v:
            continue
        elif rank[u] > rank[v]:
            parent[v] = u
        else:
            parent[u] = v
            if rank[u] == rank[v]:
                rank[v] += 1

    def dfs(node, parent):
        for neighbor, is_root in graph[node]:
            if neighbor == parent:
                continue
            if is_root:
                maximum[root] = max(maximum[node], maximum[neighbor])
            else:
                solution = max(solution, dfs(neighbor, node) + (1 if is_root else 0))
                minimum[node] = min(minimum[node], minimum[neighbor] + (1 if is_root else 0))

        if not is_root and minimum[node] == max(values[node], values[parent]):
            solution = max(solution, dfs(node, parent))

    if n == 1:
        return 0

    maximum = [0] * (n+1)
    minimum = [float('inf')] * (n+1)

    for edge in edges:
        u, v = edge
        if parent[u] < 0:
            graph[u] = []
        if parent[v] < 0:
            graph[v] = []

        graph[u].append([v, u == parent[u]])
        graph[v].append([u, v == parent[v]])

    root = 0
    solution = float('inf')

    graph[root] = [(1, True, None)]
    graph[1] = [(1, False, None)]

    dfs(1, -1)

    return solution

