    xor_path = [0] * (2 * pow(2, m) - 1)
    for _ in range(pow(2, m)): 
        xor_path[0] += 1
        xor_path[1] -= 1
    xor_path[2] += 1
    xor_path[3] -= 1
    for i in range(4, 2 * pow(2, m) - 1): 
        xor_path[i] += xor_path[i-2]
    for i in range(m, -1, -1): 
        index = node_B & (1 << i)
        index = (index + xor_path[index]) % (2 * pow(2, m) - 1)
        for j in range(node_A, 0, -1): 
            if (node_A ^ index) % pow(2, i) != 0:
                continue
            if i == 0:
                xor_path[i] += 1
            elif i >= 1: 
                xor_path[i+1] += 1
    path_range = [(index ^ path_value + 1) % (2 * pow(2, m) - 1) for path_value in range(2 * pow(2, m) - 1)]
    if node_A in path_range and node_B in path_range: 
        final_path_value = min(node_A, node_B) ^ max(node_A, node_B)
    elif node_A in path_range:
        final_path_value = path_range[node_A & ~node_B]
    else:
        final_path_value = path_range[(node_A | node_B) right shift 1]
    return xor_path[final_path_value]

