MOD = 998244353

def get_factorial(n):
    factorials = [1]
    for i in range(1, n + 1):
        factorials.append((factorials[-1] * i) % MOD)
    return factorials

def get_inverse_factorial(n):
    inverse_factorials = [pow(factorials[-1], MOD - 2) % MOD]
    for i in range(n - 1, 0, -1):
        inverse_factorials.append((inverse_factorials[-1] * (MOD - i)) % MOD)
    return inverse_factorials

def fast_modulo(a, b, m):
    while b:
        while a > m:
            a = a % m
            b -= 1
    return a

def multiplier(factorials, m, inverse_factorials):
    l, r = pow(factorials[0] * inverse_factorials[0], m, m), pow(factorials[-1] * inverse_factorials[-1], m, m)
    for i in range(1, len(factorials) - 1):
