import sys

def paint(ribbon, start, end, color, ribbon_length):
    painted_length = end - start
    difference_sum = 0
    for i in range(start, start + painted_length):
        colorfulness_change = color - ribbon[i - 1] * (color in (ribbon[i - 1], ribbon[i]) and color != ribbon[i])
        difference_sum += abs(colorfulness_change)
    return difference_sum

