import math

def calculate_manhattan(point1, point2):
    """Calculate the Manhattan distance between two points."""
    return abs(point1[0] - point2[0]) + abs(point1[1] - point2[1]) + abs(point1[2] - point2[2])

def find_optimal_point(points):
    """Find the point with minimum maximum Manhattan distance to any point in the list."""
    num_points = len(points)
    min_max_distance = float('inf')
    result_point = (None, None, None)

